(function(){
const defaults={mode:'site',date:new Date(Date.now()+19800000).toISOString().slice(0,10),minutes:540,latitude:12.97,longitude:77.59,timezone:5.5,facing:135,distance:2.5,receiver:true,manual:{elevation:30,azimuth:-20,strength:3.8}};
let state=JSON.parse(JSON.stringify(defaults));
function validate(s){if(!s||!['site','manual'].includes(s.mode)||typeof s.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(s.date)||!Number.isFinite(Date.parse(s.date+'T12:00:00Z'))||new Date(s.date+'T12:00:00Z').toISOString().slice(0,10)!==s.date||typeof s.receiver!=='boolean')return false;for(const [k,min,max]of [['minutes',0,1439],['latitude',-89,89],['longitude',-180,180],['timezone',-12,14],['facing',0,359.99],['distance',1,6]])if(typeof s[k]!=='number'||!Number.isFinite(s[k])||s[k]<min||s[k]>max)return false;return !!s.manual&&[['elevation',8,80],['azimuth',-80,80],['strength',0,5]].every(([k,min,max])=>typeof s.manual[k]==='number'&&Number.isFinite(s.manual[k])&&s.manual[k]>=min&&s.manual[k]<=max)}
try{const s=JSON.parse(localStorage.getItem('jali-study-v1'));if(validate(s))state=s}catch{}
function sync(){for(const [id,key]of [['solarDate','date'],['solarTime','minutes'],['siteLatitude','latitude'],['siteLongitude','longitude'],['siteTimezone','timezone'],['wallFacing','facing'],['receiverDistance','distance']])document.getElementById(id).value=state[key];document.getElementById('showReceiver').checked=state.receiver;document.getElementById('solarTimeLabel').textContent=String(Math.floor(state.minutes/60)).padStart(2,'0')+':'+String(Math.round(state.minutes%60)).padStart(2,'0');document.getElementById('distanceLabel').textContent=window.jaliUnits.length(state.distance);document.getElementById('receiverDistance').setAttribute('aria-valuetext',window.jaliUnits.length(state.distance));document.querySelector('.site-details summary').textContent='Location & date'+(Math.abs(state.latitude-12.97)<.02&&Math.abs(state.longitude-77.59)<.02?' · Bengaluru':'');}
function set(patch){const next={...state,...patch,manual:{...state.manual,...patch.manual}};if(!validate(next))throw Error('Invalid light-study settings');state=next;sync();try{localStorage.setItem('jali-study-v1',JSON.stringify(state))}catch{}window.dispatchEvent(new CustomEvent('jali-study',{detail:JSON.parse(JSON.stringify(state))}));return JSON.parse(JSON.stringify(state))}
window.jaliStudy={get:()=>JSON.parse(JSON.stringify(state)),set,validate};
for(const [id,key]of [['solarDate','date'],['solarTime','minutes'],['siteLatitude','latitude'],['siteLongitude','longitude'],['siteTimezone','timezone'],['wallFacing','facing'],['receiverDistance','distance']]){const input=document.getElementById(id);input.addEventListener(input.type==='range'?'input':'change',()=>{try{const value=key==='date'?input.value:input.value.trim()===''?NaN:+input.value;set({[key]:value,mode:'site'})}catch{sync();document.getElementById('sunStatus').textContent='Check the date and numeric site settings.'}})}document.getElementById('showReceiver').onchange=()=>set({receiver:document.getElementById('showReceiver').checked});document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>set({minutes:+b.dataset.time,mode:'site'}));window.addEventListener('jali-units',sync);sync();
})();
